const assert = require('node:assert/strict');

        const { OrderHandler } = require('../.build/handler');
        const { OrderRepository } = require('../.build/repository');
        const handler = new OrderHandler(new OrderRepository([
          { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
          { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
          { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 }
        ]));
        assert.deepEqual(handler.list({ tenant: 'a', limit: 1 }).items.map(x => x.id), ['a']);
        assert.throws(() => handler.list({ tenant: 'a', limit: 0 }), /invalid request/);

        // Cursor pagination.
        {
          const rows = [
            { id: 'd', tenant: 'a', createdAt: '2026-03-01', total: 4 },
            { id: 'B', tenant: 'a', createdAt: '2026-01-01', total: 5 },
            { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 6 },
            { id: 'c', tenant: 'a', createdAt: '2026-02-01', total: 7 },
            { id: 'z', tenant: 'other', createdAt: '2026-01-01', total: 8 },
            { id: 'e', tenant: 'a', createdAt: '2026-02-01', total: 9 }
          ];
          const snapshot = JSON.stringify(rows);
          const repo = new OrderRepository(rows);
          const h = new OrderHandler(repo);
          const expected = ['B', 'a', 'c', 'e', 'd'];

          // Walk every page at several sizes: exact order, no repeats or skips.
          for (const limit of [1, 2, 3, 4, 5, 100]) {
            const seen = [];
            let cursor;
            let pages = 0;
            for (;;) {
              const page = cursor === undefined ? h.list({ tenant: 'a', limit }) : h.list({ tenant: 'a', limit, cursor });
              pages++;
              assert.ok(page.items.length <= limit);
              seen.push(...page.items.map(x => x.id));
              if (page.nextCursor === null) break;
              assert.ok(page.items.length > 0);
              cursor = page.nextCursor;
              assert.ok(pages < 20, 'pagination did not terminate');
            }
            assert.deepEqual(seen, expected, `limit ${limit}`);
          }

          // Exact cursor format and null when nothing further exists.
          assert.deepEqual(h.list({ tenant: 'a', limit: 2 }), {
            items: [rows[1], rows[2]], nextCursor: '2026-01-01|a'
          });
          assert.equal(h.list({ tenant: 'a', limit: 5 }).nextCursor, null);
          assert.equal(h.list({ tenant: 'a', limit: 4, cursor: '2026-02-01|e' }).nextCursor, null);
          assert.deepEqual(h.list({ tenant: 'a', limit: 4, cursor: '2026-02-01|e' }).items.map(x => x.id), ['d']);

          // Cursor resumes after the position even if its row was deleted.
          const trimmed = new OrderHandler(new OrderRepository(rows.filter(r => r.id !== 'c')));
          assert.deepEqual(trimmed.list({ tenant: 'a', limit: 10, cursor: '2026-02-01|c' }).items.map(x => x.id), ['e', 'd']);

          // A cursor pair from another tenant still applies to this tenant's filtered list.
          assert.deepEqual(h.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|z' }).items.map(x => x.id), ['c', 'e', 'd']);
          assert.deepEqual(h.list({ tenant: 'b', limit: 10 }).items, []);

          // Invalid tenant / cursor / limit.
          for (const bad of ['', 'a', '|', 'a|', '|b', 'a|b|c', 'a||b', 'a|b|', '|a|b', 1, null]) {
            assert.throws(() => h.list({ tenant: 'a', limit: 1, cursor: bad }), /^Error: invalid request$/, `cursor ${JSON.stringify(bad)}`);
          }
          assert.throws(() => h.list({ tenant: '', limit: 1 }), /invalid request/);
          for (const bad of [0, 101, 1.5, NaN, Infinity]) {
            assert.throws(() => h.list({ tenant: 'a', limit: bad }), /invalid request/);
          }
          assert.equal(h.list({ tenant: 'a', limit: 100 }).items.length, 5);

          // Input rows and array are not mutated.
          assert.equal(JSON.stringify(rows), snapshot);
        }

