import { Order } from './types';

export interface OrderPosition {
  createdAt: string;
  id: string;
}

// Lexicographic (code-unit) ordering by createdAt, then id.
function compareOrders(a: OrderPosition, b: OrderPosition): number {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  if (a.id !== b.id) return a.id < b.id ? -1 : 1;
  return 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  list(tenant: string): Order[] {
    return this.rows.filter(row => row.tenant === tenant).sort(compareOrders);
  }

  // Returns the tenant's orders sorted by (createdAt, id) that are strictly after
  // `after`. The position does not need to correspond to an existing row.
  listAfter(tenant: string, after?: OrderPosition): Order[] {
    const matching = this.rows.filter(row => row.tenant === tenant);
    const eligible = after === undefined
      ? matching
      : matching.filter(row => compareOrders(row, after) > 0);
    return eligible.sort(compareOrders);
  }
}
